package com.esf.service.controller;

import com.esf.service.dto.ApiResponse;
import com.esf.service.dto.PageResult;
import com.esf.service.dto.ServiceOrderRequest;
import com.esf.service.dto.ServiceQueryParams;
import com.esf.service.entity.ServiceOrder;
import com.esf.service.service.ServiceOrderService;
import org.springframework.http.ResponseEntity;
import org.springframework.web.bind.annotation.GetMapping;
import org.springframework.web.bind.annotation.PathVariable;
import org.springframework.web.bind.annotation.PostMapping;
import org.springframework.web.bind.annotation.PutMapping;
import org.springframework.web.bind.annotation.RequestBody;
import org.springframework.web.bind.annotation.RequestMapping;
import org.springframework.web.bind.annotation.RequestParam;
import org.springframework.web.bind.annotation.RestController;

import java.util.Map;

@RestController
@RequestMapping("/api/services")
public class ServiceOrderController {

    private final ServiceOrderService serviceOrderService;

    public ServiceOrderController(ServiceOrderService serviceOrderService) {
        this.serviceOrderService = serviceOrderService;
    }

    @PostMapping
    public ResponseEntity<ApiResponse<ServiceOrder>> create(@RequestBody ServiceOrderRequest request) {
        ServiceOrder order = serviceOrderService.createOrder(request);
        return ResponseEntity.ok(ApiResponse.success("创建成功", order));
    }

    @GetMapping
    public ResponseEntity<ApiResponse<PageResult<ServiceOrder>>> list(
            @RequestParam(name = "type", required = false) String type,
            @RequestParam(name = "typeValue", required = false) String typeValue,
            @RequestParam(name = "orgId", required = false) String orgId,
            @RequestParam(name = "departmentId", required = false) String departmentId,
            @RequestParam(name = "skillGroupId", required = false) String skillGroupId,
            @RequestParam(name = "status", required = false) String status,
            @RequestParam(name = "current", required = false) Integer current,
            @RequestParam(name = "size", required = false) Integer size) {
        ServiceQueryParams params = new ServiceQueryParams();
        params.setType(type);
        params.setTypeValue(typeValue);
        params.setOrgId(orgId);
        params.setDepartmentId(departmentId);
        params.setSkillGroupId(skillGroupId);
        params.setStatus(status);
        if (current != null) {
            params.setCurrent(current);
        }
        if (size != null) {
            params.setSize(size);
        }
        PageResult<ServiceOrder> page = serviceOrderService.queryOrders(params);
        return ResponseEntity.ok(ApiResponse.success("查询成功", page));
    }

    @GetMapping("/stats")
    public ResponseEntity<ApiResponse<Map<String, Object>>> stats(
            @RequestParam(name = "orgId", required = false) String orgId) {
        Map<String, Object> statistics = serviceOrderService.getStatistics(orgId);
        return ResponseEntity.ok(ApiResponse.success("查询成功", statistics));
    }

    @GetMapping("/{id}")
    public ResponseEntity<ApiResponse<ServiceOrder>> detail(@PathVariable("id") Long id) {
        ServiceOrder order = serviceOrderService.getOrderById(id);
        if (order == null) {
            return ResponseEntity.status(404).body(ApiResponse.error(404, "工单不存在"));
        }
        return ResponseEntity.ok(ApiResponse.success("查询成功", order));
    }

    @PutMapping("/{id}/status")
    public ResponseEntity<ApiResponse<Map<String, Object>>> updateStatus(@PathVariable("id") Long id,
                                                                         @RequestBody Map<String, String> body) {
        Map<String, Object> result = serviceOrderService.updateStatus(id, body.get("status"), body.get("owner"));
        if (result == null) {
            return ResponseEntity.status(404).body(ApiResponse.error(404, "工单不存在"));
        }
        return ResponseEntity.ok(ApiResponse.success("更新成功", result));
    }
}

