    @Select("SELECT * FROM service_orders WHERE id = #{id}")
    ServiceOrder selectById(@Param("id") Long id);

    @Update("UPDATE service_orders SET status = #{status}, owner = #{owner}, updated_at = #{updatedAt} "
            + "WHERE id = #{id}")
